function geometry(shape){return [()=>new THREE.CylinderGeometry(.65,.65,1.8,48,1),()=>new THREE.SphereGeometry(.88,48,32),()=>new THREE.TorusGeometry(.65,.24,24,64,Math.PI),()=>new THREE.TorusGeometry(.67,.26,24,64),()=>new THREE.BoxGeometry(1.4,1.7,.22),()=>new THREE.BoxGeometry(1.3,1.3,1.3),()=>new THREE.ConeGeometry(.8,1.7,48)][shape]();}
function texture(type){const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=type==='Wood'?'#b9966a':type==='Metal'?'#a8a9a5':'#cb8c47';ctx.fillRect(0,0,256,256);let seed=12;const rand=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};for(let i=0;i<850;i++){ctx.strokeStyle=type==='Wood'?`rgba(76,43,18,${rand()*.18})`:`rgba(255,255,255,${rand()*.14})`;ctx.lineWidth=rand()*1.7;const x=rand()*256;ctx.beginPath();ctx.moveTo(x,0);ctx.bezierCurveTo(x+rand()*12,90,x-8,160,x+4,256);ctx.stroke();}return new THREE.CanvasTexture(c);}
const textures={Wood:texture('Wood'),Metal:texture('Metal'),Plastic:texture('Plastic')};
let renderer;try{renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(420,320);renderer.setClearColor(0xedece7,0);renderer.outputColorSpace=THREE.SRGBColorSpace;}catch(e){console.warn('WebGL unavailable',e);}
function sceneFor(d){const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(35,1.3,.1,100);camera.position.set(3,2.3,4);camera.lookAt(0,0,0);scene.add(new THREE.HemisphereLight(0xffffff,0x8f806c,2));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(3,5,4);scene.add(light);let mesh=new THREE.Mesh(geometry(d.shape),new THREE.MeshStandardMaterial({map:textures[d.type]||null,color:d.type==='Plastic'?(d.id===11?0xe7a2a2:0xf2ba62):0xffffff,metalness:d.type==='Metal'?.82:0,roughness:d.type==='Metal'?.3:d.type==='Plastic'?.28:.7,transparent:d.type==='Plastic',opacity:d.type==='Plastic'?.88:1}));mesh.rotation.set(.1,-.4,d.shape===2?0:.03);scene.add(mesh);if(d.shape===0){for(let i=0;i<32;i++){const angle=i*Math.PI/16;const flute=new THREE.Mesh(new THREE.CylinderGeometry(.043,.043,1.8,8),mesh.material);flute.position.set(Math.sin(angle)*.64,0,Math.cos(angle)*.64);mesh.add(flute);}}if(d.componentModel||d.concept||d.category==='reuse'||d.materialModel||modelForType[d.type]){scene.remove(mesh);mesh.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});mesh=d.componentModel?componentModel(d.componentModel,d.brand):d.concept?provisionalModel(d.concept):d.category==='reuse'?reuseModel(d.id%4):materialModel(d.materialModel||modelForType[d.type]);scene.add(mesh);}centerModel(mesh);frameModel(camera,mesh,1.3);return {scene,camera,mesh};}
function renderThumb(canvas,d){if(!fieldAllowed('model')){if(fieldAllowed('photos')&&d.photoKey){fileURL(d.photoKey).then(url=>{if(!canvas.isConnected){URL.revokeObjectURL(url);return;}const img=new Image();img.src=url;img.alt='Material photo';img.className='uploaded-thumbnail';img.onload=()=>URL.revokeObjectURL(url);canvas.replaceWith(img);}).catch(()=>{});}else{const label=document.createElement('span');label.className='preview-restricted';label.textContent='Preview not available for this profile';canvas.replaceWith(label);}return;}if(d.modelKey&&!d.photoKey)renderModelThumb(canvas,d);if(d.photoKey&&fieldAllowed('photos')){fileURL(d.photoKey).then(url=>{if(!canvas.isConnected){URL.revokeObjectURL(url);return;}const img=document.createElement('img');img.src=url;img.className='uploaded-thumbnail';img.alt=fieldAllowed('name')?d.name:'Material photo';img.onload=()=>URL.revokeObjectURL(url);canvas.replaceWith(img);}).catch(()=>{});}if(!renderer){canvas.parentElement.insertAdjacentHTML('beforeend',`<div class="fallback-object ${d.type.toLowerCase()}"></div>`);return;}const {scene,camera,mesh}=sceneFor(d);frameModel(camera,mesh,420/320);renderer.render(scene,camera);canvas.width=420;canvas.height=320;canvas.getContext('2d').drawImage(renderer.domElement,0,0,canvas.width,canvas.height);scene.traverse(o=>{if(o.geometry)o.geometry.dispose()});}
