function fillBrandStorage(){const definition=getBrandDefinition(document.querySelector('#record-brand')?.value);const storage=definition?.storage;if(storage){document.querySelector('#storage-name').value=storage.name||'';document.querySelector('#storage-address').value=storage.address||'';document.querySelector('#storage-latitude').value=storage.lat;document.querySelector('#storage-longitude').value=storage.lng;}else for(const id of ['storage-name','storage-address','storage-latitude','storage-longitude'])document.querySelector('#'+id).value='';}
